    const a = argv[i];
    if (a === '--json') opts.json = argv[++i] ?? null;
    else if (a === '--samples') opts.samples = Number(argv[++i]);
    else if (a === '--interval-ms') opts.intervalMs = Number(argv[++i]);
    else throw new Error(`unknown argument: ${a}`);
  }
